import threading, time

def download(name, seconds):
    time.sleep(seconds)
    print(f'{name} done')

threads = [threading.Thread(target=download, args=(f'file{i}', 0.2)) for i in range(3)]
start = time.time()
for t in threads: t.start()
for t in threads: t.join()
print(f'All done in {time.time() - start:.1f}s')

import threading

counter = 0
lock = threading.Lock()

def work():
    global counter
    for _ in range(10000):
        with lock:
            counter += 1

threads = [threading.Thread(target=work) for _ in range(4)]
for t in threads: t.start()
for t in threads: t.join()
print(counter)
